// Iranian national code check, broken into steps:
// 1) format  2) weighted sum  3) compare check digit
bool isValidNationalCode(String code) {
  if (!RegExp(r'^\d{10}$').hasMatch(code)) return false;
  if (code.split('').toSet().length == 1) return false; // 1111111111

  final digits = code.split('').map(int.parse).toList();
  final checkDigit = digits[9];
  final r = weightedSum(digits.sublist(0, 9)) % 11;
  return r < 2 ? checkDigit == r : checkDigit == 11 - r;
}

int weightedSum(List<int> nineDigits) {
  var sum = 0;
  for (var i = 0; i < 9; i++) {
    sum += nineDigits[i] * (10 - i); // weights 10..2
  }
  return sum;
}

void main() {
  for (final c in ['0012345679', '1234567890', '12345']) {
    print('$c: ${isValidNationalCode(c)}'); // true, false, false
  }
}

