// O(n^2): compares every pair
bool hasDuplicateSlow(List<String> phones) {
  for (var i = 0; i < phones.length; i++) {
    for (var j = i + 1; j < phones.length; j++) {
      if (phones[i] == phones[j]) return true;
    }
  }
  return false;
}

// O(n): a single pass with a Set
bool hasDuplicateFast(List<String> phones) {
  final seen = <String>{};
  for (final p in phones) {
    if (!seen.add(p)) return true; // add returns false if present
  }
  return false;
}

void main() {
  final phones = List.generate(
      20000, (i) => '0912${i.toString().padLeft(7, '0')}');

  final sw = Stopwatch()..start();
  print('${hasDuplicateSlow(phones)} slow: ${sw.elapsedMilliseconds} ms');
  sw.reset();
  print('${hasDuplicateFast(phones)} fast: ${sw.elapsedMilliseconds} ms');
}

