int linearSearch(List<int> items, int target) {
  for (var i = 0; i < items.length; i++) {
    if (items[i] == target) return i;
  }
  return -1; // not found
}

int binarySearch(List<int> sorted, int target) {
  var low = 0, high = sorted.length - 1;
  while (low <= high) {
    final mid = (low + high) ~/ 2;
    if (sorted[mid] == target) return mid;
    if (sorted[mid] < target) low = mid + 1; // go right
    if (sorted[mid] > target) high = mid - 1; // go left
  }
  return -1;
}
void main() => print([linearSearch([7, 3, 9], 9), binarySearch([1, 4, 8, 12, 20], 12)]); // [2, 3]

