/// First index whose value is >= target (lower bound).
int lowerBound(List<int> sorted, int target) {
  var low = 0, high = sorted.length; // half-open range [low, high)
  while (low < high) {
    final mid = (low + high) ~/ 2;
    if (sorted[mid] < target) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  return low;
}

