void insertionSort(List<int> a) {
  for (var i = 1; i < a.length; i++) {
    final current = a[i];
    var j = i - 1;
    // shift bigger items one step to the right
    while (j >= 0 && a[j] > current) {
      a[j + 1] = a[j];
      j--;
    }
    a[j + 1] = current;
  }
}

void main() {
  final prices = [45000, 12000, 98000, 30000];
  insertionSort(prices);
  print(prices); // [12000, 30000, 45000, 98000]
}

