class Category {
  final String name;
  final int productCount;
  final List<Category> children;
  const Category(this.name, this.productCount, [this.children = const []]);
}

// Products in a category plus all of its sub-categories
int totalProducts(Category c) {
  var sum = c.productCount;
  for (final child in c.children) {
    sum += totalProducts(child); // recursive call
  }
  return sum; // leaf: no children, so no recursion (base case)
}

void printTree(Category c, [int depth = 0]) {
  print('${'  ' * depth}- ${c.name} (${totalProducts(c)})');
  for (final child in c.children) {
    printTree(child, depth + 1);
  }
}

void main() {
  const shop = Category('پوشاک', 0, [
    Category('مردانه', 5, [Category('پیراهن', 40), Category('کفش', 25)]),
    Category('زنانه', 10, [Category('مانتو', 60)]),
  ]);
  printTree(shop); // root shows 140
}

