import 'package:test/test.dart';

class OtpService {
  final Random _random;
  final DateTime Function() _now;
  final _codes = <String, (String code, DateTime expires)>{};
  OtpService({Random? random, DateTime Function()? now})
      : _random = random ?? Random.secure(),
        _now = now ?? DateTime.now;
  String send(String mobile) {
    final code = (_random.nextInt(9000) + 1000).toString(); // 4 digits
    _codes[mobile] = (code, _now().add(const Duration(minutes: 2)));
    return code; // in production: send via SMS instead
  }
  bool verify(String mobile, String code) {
    final entry = _codes[mobile];
    if (entry == null) return false;
    return entry.$1 == code && _now().isBefore(entry.$2);
  }
}

void main() {
  test('code expires after 2 minutes', () {
    var now = DateTime(2025, 1, 1, 10, 0);
    final otp = OtpService(random: Random(42), now: () => now);
    final code = otp.send('09121234567');
    expect(otp.verify('09121234567', code), isTrue);
    now = now.add(const Duration(minutes: 3)); // time travel!
    expect(otp.verify('09121234567', code), isFalse);
  });
