import 'package:dio/dio.dart';

class Product {
  final int id;
  final String name;
  final int price; // toman
  const Product(this.id, this.name, this.price);
}

abstract interface class ProductRepository {
  Future<List<Product>> getProducts();
}
class NetworkFailure implements Exception {}
class ProductRepositoryImpl implements ProductRepository {
  final Dio _dio;
  List<Product>? _cache; // last successful result
  ProductRepositoryImpl(this._dio);
  @override
  Future<List<Product>> getProducts() async {
    try {
      final res = await _dio.get<List<dynamic>>('/products');
      return _cache = [
        for (final j in res.data!.cast<Map<String, dynamic>>())
          Product(j['id'] as int, j['title'] as String, (j['price_rial'] as int) ~/ 10),
      ];
    } on DioException {
      final cached = _cache;
      if (cached != null) return cached; // offline: show last data
      throw NetworkFailure(); // domain error, not DioException
    }
  }
}

